_log = pd.read_csv(os.path.join(HERE, '..', 'gold_sleeve', 'output', 'gold_sleeve_monthly_log.csv'), index_col=0, parse_dates=True)
def _st(r):
    r = r.dropna(); eq = (1 + r).cumprod(); y = len(r) / 12
    return dict(cagr=eq.iloc[-1] ** (1 / y) - 1, vol=r.std() * 12 ** 0.5, sharpe=((r - (1.06 ** (1 / 12) - 1)).mean() / r.std()) * 12 ** 0.5, maxdd=(eq / eq.cummax() - 1).min())
_pvf, _pvh = _st(_log['net_return']), _st(_log.loc[_log.index >= '2015-01-01', 'net_return'])
_pl_lo, _pl_hi = 0.5 * _pvh['sharpe'], 0.8 * _pvh['sharpe']
_cg = lambda sh: 0.06 + sh * _pvh['vol'] - _pvh['vol'] ** 2 / 2
PV = dict(full=_pvf, hold=_pvh, sh_lo=_pl_lo, sh_hi=_pl_hi, cg_lo=_cg(_pl_lo), cg_hi=_cg(_pl_hi), dd_lo=_pvf['maxdd'] * 1.25, dd_hi=_pvf['maxdd'] * 1.5)
_gm = pd.read_csv(os.path.join(HERE, 'results', 'stage14_portfolio_marginal.csv'))
GM = _gm[(_gm.idea == 'Gold buy&hold') & (_gm.w == 0.2)].iloc[0]
pct = lambda x, d=1: '–' if pd.isna(x) else f'{x*100:.{d}f}%'
num = lambda x, d=2: '–' if pd.isna(x) else f'{x:.{d}f}'
sgn = lambda x, d=2: '–' if pd.isna(x) else f'{x:+.{d}f}'


def md(rows, header):
    out = ['| ' + ' | '.join(header) + ' |', '|' + '|'.join(['---'] * len(header)) + '|']
    out += ['| ' + ' | '.join(str(c) for c in r) + ' |' for r in rows]
    return '\n'.join(out)


